(() => {
  function initHeroAnimation(){const tl=gsap.timeline({defaults:{ease:'power3.out'}});tl.from('.header .brand,.hero .eyebrow',{opacity:0,y:12,duration:.5}).from('.hero h1 .line>span',{yPercent:105,stagger:.12,duration:.9},'-.2').from('.hero-description,.hero .actions,.hero-rating',{opacity:0,y:20,stagger:.12,duration:.65},'-.5').from('.hero-visual',{opacity:0,scale:.96,clipPath:'inset(0 100% 0 0)',duration:1.1},'-.7');}
  function initTransformationAnimation(){gsap.fromTo('.comparison-after .surface-light',{opacity:.25,scale:1.2},{opacity:1,scale:1,scrollTrigger:{trigger:'.transformation',start:'top 75%',end:'bottom 60%',scrub:1}});gsap.from('.transformation-stages span',{opacity:.3,stagger:.25,scrollTrigger:{trigger:'.comparison',start:'top 60%',end:'bottom 35%',scrub:1}});}
  function initServicesAnimation(){gsap.utils.toArray('.service-visual').forEach(el=>gsap.from(el,{clipPath:'inset(0 0 16% 0)',duration:1,scrollTrigger:{trigger:el,start:'top 85%',once:true}}));}
  function initProcessAnimation(){gsap.from('.process li',{opacity:.35,x:-12,stagger:.12,duration:.6,scrollTrigger:{trigger:'.process ol',start:'top 80%',once:true}});}
  function initTestimonialsAnimation(){gsap.from('.rating-block strong',{opacity:0,scale:.8,duration:.6,scrollTrigger:{trigger:'.rating-block',start:'top 85%',once:true}});}
  function initCTAAnimation(){gsap.from('.final-cta h2',{clipPath:'inset(0 0 100% 0)',duration:1,scrollTrigger:{trigger:'.final-cta',start:'top 70%',once:true}});}
  function initQualityAnimation(){const steps=gsap.utils.toArray('.quality-step'),photos=gsap.utils.toArray('.quality-photo');ScrollTrigger.create({trigger:'.quality',start:'top top',end:'+=1500',pin:true,onUpdate:self=>{const active=Math.min(3,Math.floor(self.progress*4));steps.forEach((s,i)=>s.classList.toggle('active',i===active));photos.forEach((s,i)=>s.classList.toggle('active',i===active));}});}
  function initEmotionAnimation(pin){const words=gsap.utils.toArray('.emotion p');const tl=gsap.timeline({scrollTrigger:{trigger:'.emotion',start:pin?'top top':'top 75%',end:pin?'+=1200':'bottom 30%',pin,scrub:1}});words.forEach((word,i)=>tl.fromTo(word,{opacity:.17,y:25},{opacity:1,y:0,duration:1},i));tl.to({}, {duration:1});}
  window.initAnimations=()=>{if(!window.gsap||!window.ScrollTrigger)return;gsap.registerPlugin(ScrollTrigger);const mm=gsap.matchMedia();mm.add('(prefers-reduced-motion: no-preference)',()=>{initHeroAnimation();initTransformationAnimation();initServicesAnimation();initProcessAnimation();initTestimonialsAnimation();initCTAAnimation();});mm.add('(min-width: 1025px) and (prefers-reduced-motion: no-preference)',()=>{initQualityAnimation();initEmotionAnimation(true);gsap.to('.hero-photo',{yPercent:5,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}});});mm.add('(min-width: 769px) and (max-width: 1024px) and (prefers-reduced-motion: no-preference)',()=>initEmotionAnimation(false));mm.add('(max-width: 768px) and (prefers-reduced-motion: no-preference)',()=>initEmotionAnimation(false));mm.add('(pointer: fine) and (min-width: 1025px) and (prefers-reduced-motion: no-preference)',()=>{const clean=[];document.querySelectorAll('.button').forEach(b=>{const move=event=>{const r=b.getBoundingClientRect();gsap.to(b,{x:(event.clientX-r.left-r.width/2)*.07,y:(event.clientY-r.top-r.height/2)*.1,duration:.3});};const leave=()=>gsap.to(b,{x:0,y:0,duration:.3});b.addEventListener('pointermove',move);b.addEventListener('pointerleave',leave);clean.push(()=>{b.removeEventListener('pointermove',move);b.removeEventListener('pointerleave',leave);gsap.set(b,{clearProps:'transform'});});});return()=>clean.forEach(fn=>fn());});};
})();
